// Actual AppKit controls + synthetic private transport. No physical input,
// production admission, installer controller, filesystem install or paid API.
#import "InstallerUI.h"

static NSString * const Plan = @"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
static NSString * const Transaction = @"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
static NSString * const Target = @"/Users/synthetic/Applications/DSH SEP.app";
static NSDictionary *Preview(void) {return @{ @"status":@"pass",@"phase":@"preview",@"preview":@{@"planHash":Plan,@"transactionId":Transaction,@"target":Target,@"dataRoot":@"/Users/synthetic/Library/Application Support/DSH SEP",@"entries":@2,@"totalBytes":@12345,@"createApplications":@YES} };}
static NSDictionary *Committed(void) {return @{@"status":@"pass",@"phase":@"committed",@"installation":@{@"target":Target,@"transactionId":Transaction,@"applicationStarted":@NO}};}

@interface FixtureTransport : NSObject <SEPInstallerPrivateTransport>
@property(nonatomic,strong) NSMutableArray<NSDictionary *> *requests;
@property(nonatomic,strong) NSMutableArray *callbacks;
@property(nonatomic,copy) void (^termination)(NSInteger,BOOL);
@end
@implementation FixtureTransport
- (instancetype)init {if((self=[super init])){_requests=[NSMutableArray new];_callbacks=[NSMutableArray new];}return self;}
- (void)requestOperation:(NSString *)operation input:(NSDictionary *)input completion:(void (^)(NSDictionary *))completion {[_requests addObject:@{@"operation":operation,@"input":[input copy]}];[_callbacks addObject:[completion copy]];}
- (void)observeTermination:(void (^)(NSInteger,BOOL))observer {_termination=[observer copy];}
- (void)reply:(NSDictionary *)value at:(NSUInteger)index {if(index>=_callbacks.count)return;void (^block)(NSDictionary *)=_callbacks[index];block(value);}
- (NSUInteger)count:(NSString *)operation {NSUInteger count=0;for(NSDictionary *request in _requests)if([request[@"operation"] isEqual:operation])count++;return count;}
@end
@interface FixtureOpener : NSObject <SEPInstallerApplicationOpener>
@property(nonatomic,strong) NSMutableArray<NSURL *> *urls;
@end
@implementation FixtureOpener
- (instancetype)init {if((self=[super init]))_urls=[NSMutableArray new];return self;}
- (void)openInstalledApplication:(NSURL *)url completion:(void (^)(BOOL))completion {[_urls addObject:url];completion(YES);}
@end

static void Pump(double seconds) {NSDate *end=[NSDate dateWithTimeIntervalSinceNow:seconds];do{[[NSRunLoop mainRunLoop] runMode:NSDefaultRunLoopMode beforeDate:[NSDate dateWithTimeIntervalSinceNow:0.005]];}while([end timeIntervalSinceNow]>0);}
static NSView *Find(NSView *view,NSString *identifier){if([view.identifier isEqual:identifier])return view;for(NSView *child in view.subviews){NSView *v=Find(child,identifier);if(v)return v;}return nil;}
static BOOL Click(SEPInstallerUI *ui,NSString *identifier){NSView *v=Find(ui.window.contentView,identifier);if(![v isKindOfClass:NSButton.class]||![(NSButton *)v isEnabled])return NO;[(NSButton *)v performClick:nil];Pump(0.03);return YES;}
static void Require(BOOL condition,NSString *code){if(!condition)@throw [NSException exceptionWithName:@"TestAssertion" reason:code userInfo:nil];}
static NSDictionary *Fixture(void){FixtureTransport *transport=[FixtureTransport new];FixtureOpener *opener=[FixtureOpener new];SEPInstallerUI *ui=[[SEPInstallerUI alloc]initWithTransport:transport opener:opener];[ui present];Pump(0.03);if(transport.requests.count==1&&[transport.requests[0][@"operation"] isEqual:@"listRecovery"]){[transport reply:@{@"status":@"pass",@"phase":@"recovery-list",@"recoveries":@[]} at:0];Pump(0.03);}return @{@"ui":ui,@"transport":transport,@"opener":opener};}
static void Reply(FixtureTransport *t,NSDictionary *value){Require(t.callbacks.count>0,@"no pending transport request");[t reply:value at:t.callbacks.count-1];Pump(0.03);}
static void Ready(NSDictionary *f){FixtureTransport *t=f[@"transport"];Require([t count:@"preview"]==1,@"preview must be dispatched once");Reply(t,Preview());}
static void Answer(SEPInstallerUI *ui,BOOL accept){NSWindow *sheet=ui.window.attachedSheet;Require(sheet!=nil,@"actual NSAlert sheet required");[NSApp endSheet:sheet returnCode:accept?NSAlertFirstButtonReturn:NSAlertSecondButtonReturn];Pump(0.05);}
static void Dispose(NSDictionary *f){SEPInstallerUI *ui=f[@"ui"];if(ui.window.attachedSheet)[NSApp endSheet:ui.window.attachedSheet returnCode:NSAlertSecondButtonReturn];Pump(0.02);[ui.window orderOut:nil];}
static void Run(NSString *name,void (^body)(NSDictionary *),NSMutableArray *results){NSDictionary *f=Fixture();@try{body(f);[results addObject:@{@"name":name,@"status":@"pass"}];}@catch(NSException *e){[results addObject:@{@"name":name,@"status":@"fail",@"code":e.reason?:@"ASSERTION"}];}@finally{Dispose(f);}}

int main(void){@autoreleasepool{
 [NSApplication sharedApplication];[NSApp setActivationPolicy:NSApplicationActivationPolicyAccessory];NSMutableArray *results=[NSMutableArray new];
 Run(@"startup reads recovery list before offering a fresh installation",^(NSDictionary *f){FixtureTransport *t=f[@"transport"];Require(t.requests.count==2,@"list and preview sequence missing");Require([t.requests[0][@"operation"] isEqual:@"listRecovery"]&&[t.requests[1][@"operation"] isEqual:@"preview"],@"fresh preview before recovery classification");},results);
 Run(@"real window renders only bounded reviewed summary",^(NSDictionary *f){SEPInstallerUI *ui=f[@"ui"];Require(ui.window!=nil,@"NSWindow missing");Ready(f);NSTextField *summary=(id)Find(ui.window.contentView,@"review-summary");Require([summary isKindOfClass:NSTextField.class],@"summary missing");Require([summary.stringValue containsString:Target]&&[summary.stringValue containsString:Plan],@"reviewed path/hash absent");Require(Click(ui,@"install"),@"install unavailable after preview");Require(ui.window.attachedSheet!=nil,@"confirmation sheet missing");},results);
 Run(@"install disabled until exact preview accepted",^(NSDictionary *f){SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];Require([t count:@"preview"]==1,@"preview not requested");Require(!Click(ui,@"install"),@"install must be disabled");Require([t count:@"confirm"]==0,@"confirm before review");},results);
 Run(@"actual NSAlert acceptance binds exact plan once",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];Require(Click(ui,@"install"),@"install missing");Require([t count:@"confirm"]==0,@"sent before native confirmation");Answer(ui,YES);Require([t count:@"confirm"]==1,@"confirm count");Require([t.requests.lastObject[@"input"] isEqual:@{@"planHash":Plan}],@"wrong plan binding");Require(!Click(ui,@"install"),@"busy install not disabled");Require([t count:@"confirm"]==1,@"duplicate dispatch");},results);
 Run(@"native confirmation cancellation sends no confirm",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];Require(Click(ui,@"install"),@"install missing");Answer(ui,NO);Require([t count:@"confirm"]==0,@"cancelled dialog confirmed");Require([ui.phase isEqual:@"preview"],@"preview not retained");},results);
 Run(@"cancel review binds plan and never creates installation",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];Require(Click(ui,@"cancel-review"),@"cancel control missing");Require([t count:@"cancel"]==1,@"cancel count");Require([t.requests.lastObject[@"input"] isEqual:@{@"planHash":Plan}],@"cancel wrong plan");Reply(t,@{@"status":@"pass",@"phase":@"cancelled"});Pump(0.02);Require([ui.phase isEqual:@"cancelled"],@"not cancelled");Require([t count:@"confirm"]==0,@"cancel created install");},results);
 Run(@"changed-plan rejection never accepts a replacement automatically",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];Click(ui,@"install");Answer(ui,YES);Reply(t,@{@"status":@"blocked",@"phase":@"blocked",@"code":@"SEP_INSTALLER_PLAN_CHANGED"});Pump(0.03);Require([ui.phase isEqual:@"blocked"],@"changed plan not blocked");Require([t count:@"preview"]==1&&[t count:@"confirm"]==1,@"automatic new plan dispatch");Require(!Click(ui,@"install"),@"stale approval reused");},results);
 Run(@"closing during accepted install keeps waiting without parallel close",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];Click(ui,@"install");Answer(ui,YES);[ui.window performClose:nil];Pump(0.03);Require(ui.window.isVisible,@"busy window closed");Require([t count:@"close"]==0,@"parallel close dispatch");Require(!ui.resourcesReleased,@"premature release");},results);
 Run(@"bounded recovery list preserves unknown blocked journal",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];Require(Click(ui,@"list-recovery"),@"recovery list control missing");Require([t count:@"listRecovery"]==2,@"list request missing");Reply(t,@{@"status":@"pass",@"phase":@"recovery-list",@"recoveries":@[@{@"transactionId":Transaction,@"phase":@"blocked",@"code":@"SEP_INSTALLER_JOURNAL"}]});Pump(0.03);NSTableView *table=(id)Find(ui.window.contentView,@"recoveries");Require([table isKindOfClass:NSTableView.class]&&table.numberOfRows==1,@"blocked row omitted");[table selectRowIndexes:[NSIndexSet indexSetWithIndex:0] byExtendingSelection:NO];Pump(0.02);Require(!Click(ui,@"resume"),@"unknown journal allowed resume");},results);
 Run(@"recovery selection requires visible native confirmation",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];Click(ui,@"list-recovery");Reply(t,@{@"status":@"pass",@"phase":@"recovery-list",@"recoveries":@[@{@"transactionId":Transaction,@"phase":@"executing"}]});Pump(0.03);NSTableView *table=(id)Find(ui.window.contentView,@"recoveries");Require([table isKindOfClass:NSTableView.class],@"recovery table missing");[table selectRowIndexes:[NSIndexSet indexSetWithIndex:0] byExtendingSelection:NO];Pump(0.03);Require(Click(ui,@"resume"),@"resume missing");Require([t count:@"resume"]==0,@"resume before confirmation");Answer(ui,YES);Require([t.requests.lastObject[@"input"] isEqual:@{@"transactionId":Transaction}],@"wrong recovery binding");},results);
 Run(@"oversized recovery list fails closed without truncation",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];Click(ui,@"list-recovery");NSMutableArray *rows=[NSMutableArray new];for(int n=0;n<65;n++)[rows addObject:@{@"transactionId":[NSString stringWithFormat:@"%032x",n],@"phase":@"committed"}];Reply(t,@{@"status":@"pass",@"phase":@"recovery-list",@"recoveries":rows});Pump(0.03);Require([ui.phase isEqual:@"blocked"],@"oversized list accepted");},results);
 Run(@"commit does not launch; separate Open control uses exact installed URL",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];FixtureOpener *opener=f[@"opener"];Click(ui,@"install");Answer(ui,YES);Reply(t,Committed());Pump(0.03);Require([ui.phase isEqual:@"committed"],@"commit missing");Require(opener.urls.count==0,@"auto launched on commit");Require(Click(ui,@"open-installed"),@"Open control missing");Require(opener.urls.count==1&&[opener.urls[0].path isEqual:Target],@"wrong LaunchServices target");},results);
 Run(@"closed receipt alone cannot release while child still lives",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];[ui.window performClose:nil];Pump(0.03);Require([t count:@"close"]==1,@"close not requested");Reply(t,@{@"status":@"pass",@"phase":@"closed",@"resourcesReleased":@YES});Pump(0.03);Require(!ui.resourcesReleased&&ui.window.isVisible,@"receipt alone released");Require(t.termination!=nil,@"termination observer missing");t.termination(0,NO);Pump(0.03);Require(ui.resourcesReleased&&[ui.phase isEqual:@"closed"],@"true closure not acknowledged");},results);
 Run(@"child exit before closed receipt is ordered safely",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];[ui.window performClose:nil];Pump(0.03);Require(t.termination!=nil,@"termination observer missing");t.termination(0,NO);Pump(0.02);Require(!ui.resourcesReleased,@"exit alone released");Reply(t,@{@"status":@"pass",@"phase":@"closed",@"resourcesReleased":@YES});Pump(0.03);Require(ui.resourcesReleased,@"late receipt not reconciled");},results);
 Run(@"blocked close and abnormal child exit cannot claim cleanup",^(NSDictionary *f){Ready(f);SEPInstallerUI *ui=f[@"ui"];FixtureTransport *t=f[@"transport"];[ui.window performClose:nil];Pump(0.03);Reply(t,@{@"status":@"blocked",@"phase":@"blocked",@"code":@"SEP_INSTALLER_CLEANUP_UNCONFIRMED"});Pump(0.02);Require([ui.phase isEqual:@"blocked"]&&!ui.resourcesReleased,@"blocked close promoted");Require(t.termination!=nil,@"termination observer missing");t.termination(1,YES);Pump(0.03);Require(!ui.resourcesReleased&&ui.window.isVisible,@"abnormal exit promoted");},results);
 NSUInteger passed=0;for(NSDictionary *r in results)if([r[@"status"] isEqual:@"pass"])passed++;
 NSDictionary *receipt=@{@"schema":@1,@"status":passed==results.count?@"pass":@"fail",@"scope":@"real AppKit controls; synthetic private transport/opener; not physical input or installed application",@"definitions":@(results.count),@"passed":@(passed),@"failed":@(results.count-passed),@"results":results,@"productInstalled":@NO};NSData *json=[NSJSONSerialization dataWithJSONObject:receipt options:NSJSONWritingPrettyPrinted error:nil];fwrite(json.bytes,1,json.length,stdout);fputc('\n',stdout);return passed==results.count?0:1;
}}
